let schemaReady = null;
function ensureSchema(env) {
  if (!schemaReady) {
    schemaReady = env.DB.batch(SCHEMA.map((s) => env.DB.prepare(s))).catch((e) => {
      schemaReady = null;
      throw e;
    });
  }
  return schemaReady;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;
    const method = request.method;
    try {
      if (!env.DB) {
        return html(shell('חסר חיבור למסד הנתונים', '<p>צריך לחבר ל-Worker מסד D1 בשם <b>DB</b> (Settings → Bindings).</p>'), 500);
      }
      await ensureSchema(env);

      let m;
      if ((m = path.match(/^\/r\/([a-z0-9]{4,16})\/?$/))) {
        if (method === 'GET' || method === 'HEAD') return guestPage(env, url, m[1]);
        if (method === 'POST') return guestSubmit(request, env, url, m[1]);
        return new Response('Method not allowed', { status: 405, headers: SECURITY_HEADERS });
      }
      if ((m = path.match(/^\/r\/([a-z0-9]{4,16})\/event\.ics$/))) return guestIcs(env, m[1]);

      if (path === '/admin/login' && method === 'POST') return login(request, env, url);
      if (path === '/admin/setup' && method === 'POST') return setup(request, env, url);
      if (path === '/admin/logout' && method === 'POST') return logout(url);
      if (path === '/admin' || path === '/admin/') {
        if (await isAdmin(request, env)) return html(await adminPage(env, url));
        const auth = await getAuth(env);
        return auth.mode === 'setup' ? setupPage('') : loginPage(false, 200);
      }
      if (path.startsWith('/api/')) {
        if (!(await isAdmin(request, env))) return json({ error: 'unauthorized' }, 401);
        if (method !== 'GET' && !sameOrigin(request, url)) return json({ error: 'bad origin' }, 403);
        return api(request, env, url);
      }
      if (path === '/' || path === '/rsvp' || path === '/rsvp/') {
        if (method === 'POST') return generalSubmit(request, env, url);
        const s = await getSettings(env);
        return html(generalHTML(s.event, { map: s.map, origin: url.origin }));
      }
      if (path === '/map' || path === '/map/thumb') return mapImage(env, path === '/map' ? 'map' : 'mapthumb');
      if (path === '/waze') {
        const { event } = await getSettings(env);
        return new Response(null, { status: 302, headers: { ...SECURITY_HEADERS, Location: wazeLink(event), 'Cache-Control': 'no-store' } });
      }
      return html(shell('הדף לא נמצא', '<h1 class="h">הדף לא נמצא</h1><p>כדאי לפתוח שוב את הלינק מההודעה בוואטסאפ.</p>'), 404);
    } catch (err) {
      console.error(err);
      if (path.startsWith('/api/')) return json({ error: 'server error' }, 500);
      return html(shell('תקלה', '<h1 class="h">משהו השתבש</h1><p>נסו לרענן את הדף בעוד רגע.</p>'), 500);
    }
  },
};

/* ------------------------------------------------------------------ helpers */

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}
function html(body, status = 200, extra = {}) {
  return new Response(body, { status, headers: { ...SECURITY_HEADERS, 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', ...extra } });
}
function json(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: { ...SECURITY_HEADERS, 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' } });
}
function str(v, max, multiline = false) {
  let s = String(v == null ? '' : v).slice(0, max);
  if (!multiline) s = s.replace(/[\r\n\t]+/g, ' ');
  return s;
}
function clampInt(v, min, max, fallback) {
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback;
}
function parseJSON(s) {
  try { return JSON.parse(s) || {}; } catch { return {}; }
}
async function readJSON(request) {
  try { return await request.json(); } catch { return null; }
}
function intlPhone(p) {
  let d = String(p || '').replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2);
  if (d.startsWith('0')) d = '972' + d.slice(1);
  return d.length >= 11 && d.length <= 13 ? d : '';
}
function newCode(taken) {
  for (;;) {
    const bytes = crypto.getRandomValues(new Uint8Array(7));
    let c = '';
    for (const b of bytes) c += CODE_CHARS[b % CODE_CHARS.length];
    if (!taken.has(c)) { taken.add(c); return c; }
  }
}
function toGuest(r) {
  return {
    id: r.id, code: r.code, name: r.name, phone: r.phone, group: r.grp, invited: r.invited,
    status: r.status, count: r.count, note: r.note, source: r.source, answeredAt: r.answered_at,
    reminders: r.reminders, lastReminder: r.last_reminder,
  };
}
async function getGuestByCode(env, code) {
  return env.DB.prepare('SELECT * FROM guests WHERE code = ?1').bind(code).first();
}
async function getSettings(env) {
  const { results } = await env.DB.prepare("SELECT key, value FROM settings WHERE key IN ('event', 'tpl', 'mapmeta')").all();
  const rows = Object.fromEntries((results || []).map((r) => [r.key, r.value]));
  const tpl = { ...DEFAULT_TPL, ...parseJSON(rows.tpl) };
  const savedGeneral = String(tpl.general || '').replace(/\r\n/g, '\n');
  if (savedGeneral === OLD_GENERAL || savedGeneral === PREV_GENERAL) tpl.general = DEFAULT_TPL.general;
  const meta = parseJSON(rows.mapmeta);
  return { event: { ...DEFAULT_EVENT, ...parseJSON(rows.event) }, tpl, map: meta && meta.v ? { v: meta.v } : null };
}

/* The dashboard page: a copy saved in D1 wins, so the page can be updated without redeploying the Worker. */
async function adminPage(env, url) {
  if (!url.searchParams.has('builtin')) {
    const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'adminhtml'").first();
    if (row && typeof row.value === 'string' && row.value.includes('</html>')) return row.value;
  }
  return ADMIN_HTML;
}

/*
 * Reset after testing. The "baseline" is the state right after the guest list was loaded:
 * one entry per invitation with its starting answer (most are pending, some were confirmed in the host's sheet).
 * A reset deletes every row that is not in the baseline (test rows, answers through the general link)
 * and puts every baseline row back to its starting answer, with no reminders sent.
 */
async function getBaseline(env) {
  const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'baseline'").first();
  const b = row && parseJSON(row.value);
  return b && b.rows && typeof b.rows === 'object' ? b : null;
}
async function saveBaseline(env, b) {
  await env.DB.prepare(UPSERT).bind('baseline', JSON.stringify(b)).run();
}
function baselineEntry(r) {
  return { s: r.status, c: r.count, src: r.source == null ? null : r.source, at: r.answered_at == null ? null : r.answered_at, note: r.note || '', inv: r.invited };
}
async function checkResetPin(env, pin) {
  const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'resetpin'").first();
  const cfg = row && parseJSON(row.value);
  if (cfg && cfg.salt && cfg.hash) {
    const digest = await crypto.subtle.digest('SHA-256', enc.encode(cfg.salt + ':' + pin));
    const hex = [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
    return safeEqual(hex, String(cfg.hash));
  }
  return env.RESET_PIN ? safeEqual(pin, String(env.RESET_PIN)) : null; // null: no code configured
}
// Locked rows (confirmations that came from the host's sheet) are never touched by a reset, whatever was edited since.
function isLocked(base, id) {
  const k = base && base.rows[String(id)];
  return !!(k && k.lock);
}
async function resetPlan(env) {
  const base = await getBaseline(env);
  const { results } = await env.DB.prepare('SELECT * FROM guests ORDER BY name').all();
  const remove = [], revert = [], locked = [];
  let keepTotal = 0, keepYes = 0;
  for (const r of results || []) {
    let k;
    if (base) k = base.rows[String(r.id)];
    else if (r.grp !== GENERAL_GROUP && r.grp !== TEST_GROUP) k = { s: 'pending', c: 0, src: null, at: null, note: '', inv: r.invited };
    if (!k) { remove.push(r); continue; }
    keepTotal++;
    if (k.lock) { locked.push(r); continue; }
    if (k.s === 'yes') keepYes++;
    const changed = r.status !== k.s || Number(r.count) !== Number(k.c) || (r.note || '') !== (k.note || '') ||
      Number(r.invited) !== Number(k.inv) || (r.source == null ? null : r.source) !== (k.src == null ? null : k.src) || (r.reminders || 0) > 0;
    if (changed) revert.push({ r, k });
  }
  return { base, remove, revert, locked, keepTotal, keepYes };
}

/* The arrival map: uploaded from the dashboard, kept in D1 as base64 (full size and a small copy for link previews). */
async function mapImage(env, key) {
  const row = await env.DB.prepare('SELECT value FROM settings WHERE key = ?1').bind(key).first();
  const img = row && parseJSON(row.value);
  if (!img || !img.data || !MAP_TYPES.includes(img.type)) return new Response('Not found', { status: 404, headers: SECURITY_HEADERS });
  const bin = atob(img.data);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, { headers: { ...SECURITY_HEADERS, 'Content-Type': img.type, 'Cache-Control': 'public, max-age=300' } });
}
function mapBlock(ev, map) {
  const waze = ev.address || ev.venue ? '<a class="btn" href="/waze" target="_blank" rel="noopener noreferrer">ניווט בוויז</a>' : '';
  if (!map) return waze ? '<div class="links">' + waze + '</div>' : '';
  const src = '/map?v=' + encodeURIComponent(map.v);
  return '<div class="mapbox"><a href="' + src + '" target="_blank" rel="noopener"><img class="map" src="' + src + '" alt="מפת הגעה לאירוע"></a>' +
    '<div class="links">' + waze + '<a class="btn" href="' + src + '" target="_blank" rel="noopener">הגדלת המפה</a></div></div>';
}
function ogImage(map, origin) {
  if (!map || !origin) return '';
  return '<meta property="og:image" content="' + esc(origin + '/map/thumb?v=' + encodeURIComponent(map.v)) + '">' +
    '<meta property="og:image:alt" content="מפת הגעה לאירוע"><meta name="twitter:card" content="summary_large_image">';
}

/* dates: event dates are stored as YYYY-MM-DD and formatted at noon UTC so they never shift a day */
function dayOf(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
  return m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3], 12)) : null;
}
function fmt(d, opts, locale = 'he-IL') {
  try { return new Intl.DateTimeFormat(locale, { timeZone: 'UTC', ...opts }).format(d); } catch { return ''; }
}
const weekday = (d) => fmt(d, { weekday: 'long' });
const dateLong = (d) => fmt(d, { day: 'numeric', month: 'long', year: 'numeric' });
const dateShort = (d) => fmt(d, { day: 'numeric', month: 'long' });
/* Hebrew date with letters, e.g. ט״ז בכסלו תשפ״ז (Intl only gives digits: 16 בכסלו 5787) */
function gematria(n) {
  const ones = ['', 'א', 'ב', 'ג', 'ד', 'ה', 'ו', 'ז', 'ח', 'ט'];
  const tens = ['', 'י', 'כ', 'ל', 'מ', 'נ', 'ס', 'ע', 'פ', 'צ'];
  const hundreds = ['', 'ק', 'ר', 'ש', 'ת', 'תק', 'תר', 'תש', 'תת', 'תתק'];
  const r = n % 100;
  const s = hundreds[Math.floor(n / 100)] + (r === 15 ? 'טו' : r === 16 ? 'טז' : tens[Math.floor(r / 10)] + ones[r % 10]);
  return s.length === 1 ? s + '׳' : s.slice(0, -1) + '״' + s.slice(-1);
}
function hebDate(d) {
  try {
    const parts = new Intl.DateTimeFormat('he-IL-u-ca-hebrew', { timeZone: 'UTC', day: 'numeric', month: 'long', year: 'numeric' }).formatToParts(d);
    const get = (t) => (parts.find((p) => p.type === t) || {}).value;
    const day = parseInt(get('day'), 10), year = parseInt(get('year'), 10), month = get('month');
    return day && year && month ? gematria(day) + ' ב' + month + ' ' + gematria(year % 1000) : '';
  } catch { return ''; }
}

function wazeLink(ev) {
  return 'https://waze.com/ul?q=' + encodeURIComponent(ev.address || ev.venue || '') + '&navigate=yes';
}
function calLink(ev) {
  const d = dayOf(ev.date);
  if (!d) return 'https://calendar.google.com/';
  const ymd = ev.date.replace(/-/g, '');
  const t = /^\d{2}:\d{2}$/.test(ev.time) ? ev.time.replace(':', '') : '1900';
  return 'https://calendar.google.com/calendar/render?action=TEMPLATE&text=' + encodeURIComponent('בר המצווה של ' + ev.boy) +
    '&dates=' + ymd + 'T' + t + '00/' + ymd + 'T235900&ctz=Asia/Jerusalem&location=' +
    encodeURIComponent([ev.venue, ev.address].filter(Boolean).join(', '));
}

/* ------------------------------------------------------------------ auth */

const enc = new TextEncoder();
function b64url(buf) {
  let s = '';
  for (const b of new Uint8Array(buf)) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
async function hmac(secret, msg) {
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return b64url(await crypto.subtle.sign('HMAC', key, enc.encode(msg)));
}
function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
function getCookie(request, name) {
  const header = request.headers.get('Cookie') || '';
  for (const part of header.split(';')) {
    const i = part.indexOf('=');
    if (i > -1 && part.slice(0, i).trim() === name) return part.slice(i + 1).trim();
  }
  return null;
}
/*
 * The admin password comes from one of two places:
 *  1. an ADMIN_PASSWORD secret on the Worker (optional, always wins), or
 *  2. a password chosen on the first visit to /admin, stored in D1 as a PBKDF2 hash.
 * Sessions are signed with a key derived from whichever is in use, so changing it logs everyone out.
 */
async function getAuth(env) {
  if (env.ADMIN_PASSWORD) return { mode: 'secret', key: 'secret:' + env.ADMIN_PASSWORD };
  const row = await env.DB.prepare("SELECT value FROM settings WHERE key = 'admin'").first();
  if (!row) return { mode: 'setup' };
  const a = parseJSON(row.value);
  if (!a.key || !a.salt || !a.hash) return { mode: 'setup' };
  return { mode: 'db', key: 'db:' + a.key, salt: a.salt, hash: a.hash };
}
function randomB64(n) {
  return b64url(crypto.getRandomValues(new Uint8Array(n)));
}
async function pbkdf2(password, salt) {
  const key = await crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: enc.encode(salt), iterations: 100000 }, key, 256);
  return b64url(bits);
}
async function isAdmin(request, env) {
  const c = getCookie(request, COOKIE);
  if (!c) return false;
  const [exp, sig] = c.split('.');
  if (!exp || !sig || !/^\d+$/.test(exp) || Number(exp) < Date.now()) return false;
  const auth = await getAuth(env);
  if (auth.mode === 'setup') return false;
  return safeEqual(sig, await hmac(auth.key, 'session:' + exp));
}
async function sessionResponse(url, auth) {
  const exp = Date.now() + SESSION_DAYS * DAY;
  const value = exp + '.' + (await hmac(auth.key, 'session:' + exp));
  return new Response(null, {
    status: 303,
    headers: { ...SECURITY_HEADERS, Location: url.origin + '/admin', 'Set-Cookie': cookieHeader(url, value, SESSION_DAYS * 86400), 'Cache-Control': 'no-store' },
  });
}
function sameOrigin(request, url) {
  const origin = request.headers.get('Origin');
  return !origin || origin === url.origin;
}
function cookieHeader(url, value, maxAge) {
  return `${COOKIE}=${value}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAge}` + (url.protocol === 'https:' ? '; Secure' : '');
}
async function login(request, env, url) {
  const auth = await getAuth(env);
  if (auth.mode === 'setup') return setupPage('');
  let password = '';
  try { password = String((await request.formData()).get('password') || ''); } catch { /* empty */ }
  const ok = auth.mode === 'secret'
    ? safeEqual(await hmac('login', password), await hmac('login', env.ADMIN_PASSWORD))
    : safeEqual(await pbkdf2(password, auth.salt), auth.hash);
  if (!ok) {
    await new Promise((r) => setTimeout(r, 600)); // slow down guessing
    return loginPage(true, 401);
  }
  return sessionResponse(url, auth);
}
async function setup(request, env, url) {
  if ((await getAuth(env)).mode !== 'setup') return loginPage(false, 409);
  let form;
  try { form = await request.formData(); } catch { form = new FormData(); }
  const password = String(form.get('password') || '');
  const confirm = String(form.get('confirm') || '');
  if (password.length < 6) return setupPage('הסיסמה צריכה להיות באורך 6 תווים לפחות.');
  if (password !== confirm) return setupPage('שתי הסיסמאות לא זהות. נסה שוב.');
  const salt = randomB64(16);
  const record = { salt, hash: await pbkdf2(password, salt), key: randomB64(32), createdAt: new Date().toISOString() };
  // DO NOTHING on conflict: if two people race here, only the first password is kept.
  const res = await env.DB.prepare("INSERT INTO settings (key, value) VALUES ('admin', ?1) ON CONFLICT(key) DO NOTHING")
    .bind(JSON.stringify(record)).run();
  if (!res.meta || res.meta.changes !== 1) return loginPage(false, 409);
  return sessionResponse(url, { key: 'db:' + record.key });
}
function logout(url) {
  return new Response(null, {
    status: 303,
    headers: { ...SECURITY_HEADERS, Location: url.origin + '/admin', 'Set-Cookie': cookieHeader(url, '', 0), 'Cache-Control': 'no-store' },
  });
}
function setupPage(error) {
  const body =
    '<h1 class="h">ברוכים הבאים ללוח אישורי ההגעה</h1>' +
    '<p>זו הכניסה הראשונה. בחר סיסמה ללוח הבקרה. רק מי שיודע אותה יוכל לראות את רשימת המוזמנים.</p>' +
    (error ? '<p class="alert">' + esc(error) + '</p>' : '') +
    '<form method="post" action="/admin/setup" class="stack">' +
    '<div class="field"><label for="pw">סיסמה חדשה</label><input id="pw" name="password" type="password" autocomplete="new-password" minlength="6" required autofocus></div>' +
    '<div class="field"><label for="pw2">שוב, לאימות</label><input id="pw2" name="confirm" type="password" autocomplete="new-password" minlength="6" required></div>' +
    '<button class="btn primary block" type="submit">שמירה וכניסה</button></form>';
  return html(shell('בחירת סיסמה', body), error ? 400 : 200);
}
function loginPage(failed, status) {
  const body =
    '<h1 class="h">לוח אישורי ההגעה</h1>' +
    (failed ? '<p class="alert">הסיסמה לא נכונה. נסה שוב.</p>' : '') +
    '<form method="post" action="/admin/login" class="stack">' +
    '<div class="field"><label for="pw">סיסמה</label><input id="pw" name="password" type="password" autocomplete="current-password" required autofocus></div>' +
    '<button class="btn primary block" type="submit">כניסה</button></form>';
  return html(shell('כניסה ללוח', body), status);
}

/* ------------------------------------------------------------------ guest pages */

const GUEST_CSS = `
:root{--bg:#F4F6FA;--surface:#FFFFFF;--sunken:#ECF0F6;--ink:#14203A;--muted:#5C6780;--line:#DCE2EC;--tekhelet:#21509F;--tekhelet-hover:#1A4287;--on-tekhelet:#FFFFFF;--tekhelet-soft:#E3EBF8;--yes:#1B7549;--yes-soft:#DFF1E6;--maybe:#8E5C08;--maybe-soft:#FAEED5;--no:#AE3A3C;--no-soft:#F7E3E2;--pending:#636D86;--pending-soft:#E9EDF3;--display:"Frank Ruhl Libre","David","Times New Roman",serif;--sans:"IBM Plex Sans Hebrew","Arial Hebrew","Segoe UI",Arial,sans-serif;color-scheme:light}
@media (prefers-color-scheme:dark){:root{--bg:#0D1320;--surface:#151D2E;--sunken:#1B2438;--ink:#E6EBF5;--muted:#98A3BC;--line:#29344C;--tekhelet:#82A6EE;--tekhelet-hover:#9DBAF3;--on-tekhelet:#0D1320;--tekhelet-soft:#1B2A4A;--yes:#6CCB98;--yes-soft:#15301F;--maybe:#E5B65C;--maybe-soft:#33270F;--no:#EE8A88;--no-soft:#3A1A1B;--pending:#A3ACC2;--pending-soft:#222B3F;color-scheme:dark}}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 var(--sans);padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
h1,h2,p{margin:0}
.card{max-width:440px;margin:0 auto;min-height:100vh;background:var(--surface)}
@media (min-width:520px){body{padding-block:28px}.card{min-height:0;border:1px solid var(--line);border-radius:24px;overflow:hidden}}
.tallit{height:20px;background:linear-gradient(to bottom,transparent 0 4px,var(--tekhelet) 4px 6px,transparent 6px 8px,var(--tekhelet) 8px 14px,transparent 14px 16px,var(--tekhelet) 16px 18px,transparent 18px)}
.inner{display:grid;gap:18px;padding-block:14px 30px;padding-left:max(22px,env(safe-area-inset-left,0px));padding-right:max(22px,env(safe-area-inset-right,0px))}
.to{font-size:14px;color:var(--muted)}
.title{font-family:var(--display);font-weight:900;font-size:36px;line-height:1.1;text-wrap:balance;margin-top:-8px}
.headline{font-family:var(--display);font-weight:900;font-size:32px;line-height:1.22;text-wrap:balance;margin-top:6px}
.h{font-family:var(--display);font-weight:700;font-size:28px;line-height:1.2}
.details{margin:0;display:grid;gap:10px;border-block:1px solid var(--line);padding-block:14px}
.details>div{display:grid;grid-template-columns:3.4em minmax(0,1fr);gap:10px}
.details dt{font-size:13px;color:var(--muted);padding-top:2px}
.details dd{margin:0}
.heb{font-family:var(--display);font-weight:500;color:var(--tekhelet)}
.muted{color:var(--muted)}
.small{font-size:14px}
.stack{display:grid;gap:14px}
fieldset{border:0;margin:0;padding:0;display:grid;gap:10px}
legend{padding:0;margin-bottom:10px;font-family:var(--display);font-size:24px;font-weight:700}
.opt{display:flex;align-items:center;gap:12px;border:1.5px solid var(--line);border-radius:12px;padding:13px 14px;font-size:17px;font-weight:500;cursor:pointer;background:var(--surface)}
.opt input{width:20px;height:20px;margin:0;accent-color:var(--tekhelet);flex:none}
.opt:has(input:checked){border-color:var(--tekhelet);background:var(--tekhelet-soft)}
.opt:has(input:focus-visible){outline:2px solid var(--tekhelet);outline-offset:2px}
.count-row{display:flex;align-items:center;justify-content:space-between;gap:12px;font-weight:500}
form:has(#s-no:checked) .count-row{display:none}
.field{display:grid;gap:6px}
.field label{font-size:14px;color:var(--muted)}
input[type=tel]{text-align:right}
.mapbox{display:grid;gap:10px}
.map{display:block;width:100%;height:auto;border-radius:14px;border:1px solid var(--line);background:var(--sunken)}
.hp{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);opacity:0;pointer-events:none}
input[type=text],input[type=password],input[type=tel],select{width:100%;font:inherit;color:inherit;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:10px 12px;min-height:44px}
.count-row select{width:auto;min-width:5.5em;font-weight:600;text-align:center}
:focus-visible{outline:2px solid var(--tekhelet);outline-offset:2px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;font:inherit;font-weight:500;border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:10px;padding:10px 16px;cursor:pointer;text-decoration:none;min-height:44px}
.btn:hover{background:var(--sunken)}
.btn.primary{background:var(--tekhelet);border-color:var(--tekhelet);color:var(--on-tekhelet)}
.btn.primary:hover{background:var(--tekhelet-hover)}
.btn.ghost{border-color:transparent;background:transparent;color:var(--tekhelet)}
.btn.block{width:100%;font-size:17px;padding-block:13px}
.done{display:grid;gap:12px;justify-items:start}
.mark{width:44px;height:44px;border-radius:50%;display:grid;place-items:center}
.mark svg{width:24px;height:24px}
.mark.yes{background:var(--yes-soft);color:var(--yes)}.mark.maybe{background:var(--maybe-soft);color:var(--maybe)}.mark.no{background:var(--pending-soft);color:var(--pending)}
.links{display:flex;flex-wrap:wrap;gap:8px}
.saved{font-size:14px;color:var(--yes);font-weight:500}
.alert{background:var(--no-soft);color:var(--no);border-radius:10px;padding:10px 12px;font-size:15px}
.sign{font-family:var(--display);font-size:18px;color:var(--muted);border-top:1px solid var(--line);padding-top:14px}
`;

const FONTS =
  '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>' +
  '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Frank+Ruhl+Libre:wght@500;700;900&family=IBM+Plex+Sans+Hebrew:wght@400;500;600&display=swap">';

const CHECK_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5 10 17 19 7"/></svg>';

function shell(title, body, head = '') {
  return '<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">' +
    '<meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#21509F">' +
    '<title>' + esc(title) + '</title>' + head + FONTS + '<style>' + GUEST_CSS + '</style></head>' +
    '<body><main class="card"><div class="tallit" aria-hidden="true"></div><div class="inner">' + body + '</div></main></body></html>';
}

function eventDetailsHTML(ev) {
  const d = dayOf(ev.date);
  const when = d ? weekday(d) + ', ' + dateLong(d) : '';
  const heb = d ? hebDate(d) : '';
  return '<dl class="details">' +
    (when ? '<div><dt>מתי</dt><dd>' + esc(when) + (heb ? '<br><span class="heb">' + esc(heb) + '</span>' : '') + '</dd></div>' : '') +
    (ev.time ? '<div><dt>שעה</dt><dd>קבלת פנים ' + esc(ev.time) + '</dd></div>' : '') +
    (ev.venue || ev.address ? '<div><dt>איפה</dt><dd>' + esc(ev.venue) + (ev.address ? '<br><span class="muted">' + esc(ev.address) + '</span>' : '') + '</dd></div>' : '') +
    '</dl>';
}

/* One link for everyone: the guest types a name and phone, and answers. A second answer from the same phone updates the first. */
function generalHTML(ev, { error = '', v = {}, map = null, origin = '' } = {}) {
  const d = dayOf(ev.date);
  const title = ev.boy ? 'בר המצווה של ' + ev.boy : 'בר המצווה';
  const when = d ? weekday(d) + ', ' + dateLong(d) : '';
  const rsvpBy = dayOf(ev.rsvpBy);
  const head =
    '<meta property="og:type" content="website">' +
    '<meta property="og:title" content="' + esc(headlineOf(ev)) + '">' +
    '<meta property="og:description" content="' + esc([when, ev.venue, 'אישור הגעה ומפת הגעה'].filter(Boolean).join(' · ')) + '">' +
    ogImage(map, origin) + headlineFont(ev).link;
  const opt = (s, label) =>
    '<label class="opt"><input type="radio" name="status" value="' + s + '" id="s-' + s + '"' + (v.status === s ? ' checked' : '') + ' required><span>' + label + '</span></label>';
  const current = clampInt(v.count, 1, 15, 2);
  let options = '';
  for (let i = 1; i <= 15; i++) options += '<option value="' + i + '"' + (i === current ? ' selected' : '') + '>' + i + '</option>';
  const body =
    '<h1 class="headline" style="' + headlineFont(ev).style + '">' + esc(headlineOf(ev)) + '</h1>' +
    eventDetailsHTML(ev) +
    mapBlock(ev, map) +
    (error ? '<p class="alert">' + esc(error) + '</p>' : '') +
    '<form method="post" action="/" class="stack">' +
    '<div class="field"><label for="name">שם</label><input type="text" id="name" name="name" maxlength="120" required autocomplete="name" placeholder="למשל: משפחת כהן" value="' + esc(v.name) + '"></div>' +
    '<div class="field"><label for="phone">טלפון (לתזכורת לפני האירוע)</label><input type="tel" id="phone" name="phone" maxlength="40" required autocomplete="tel" inputmode="tel" dir="ltr" placeholder="050-1234567" value="' + esc(v.phone) + '"></div>' +
    '<fieldset><legend>תגיעו?</legend>' + opt('yes', 'כן, נגיע') + opt('no', 'לא נוכל להגיע') + opt('maybe', 'עוד לא יודעים') + '</fieldset>' +
    '<div class="count-row"><label for="count">כמה תהיו?</label><select id="count" name="count">' + options + '</select></div>' +
    '<div class="field"><label for="note">הערה (לא חובה)</label><input type="text" id="note" name="note" maxlength="300" value="' + esc(v.note) + '" placeholder="למשל: אחד מאיתנו צמחוני" autocomplete="off"></div>' +
    '<div class="hp" aria-hidden="true"><label for="website">אתר</label><input type="text" id="website" name="website" tabindex="-1" autocomplete="off"></div>' +
    (rsvpBy ? '<p class="small muted">נשמח לתשובה עד ' + esc(dateShort(rsvpBy)) + '</p>' : '') +
    '<button class="btn primary block" type="submit">שליחת תשובה</button>' +
    '</form>' +
    '<p class="small muted">כבר עניתם ורוצים לשנות? מלאו שוב עם אותו מספר טלפון.</p>' +
    (ev.sender ? '<p class="sign">מחכים לראותכם, ' + esc(ev.sender) + '</p>' : '');
  return shell(title + ' · אישור הגעה', body, head);
}

async function generalSubmit(request, env, url) {
  let data = {};
  try { data = Object.fromEntries(await request.formData()); } catch { data = {}; }
  if (data.website) {
    // filled by bots only (the field is hidden from people)
    return new Response(null, { status: 303, headers: { ...SECURITY_HEADERS, Location: url.origin + '/', 'Cache-Control': 'no-store' } });
  }
  const { event, map } = await getSettings(env);
  const name = str(data.name, 120).trim();
  const phone = str(data.phone, 40).trim();
  const status = String(data.status || '');
  const note = str(data.note, 300).trim();
  const fail = (msg) => html(generalHTML(event, { error: msg, v: { name, phone, status, count: data.count, note }, map, origin: url.origin }), 400);
  if (!name) return fail('צריך לכתוב שם.');
  const norm = intlPhone(phone);
  if (!norm) return fail('מספר הטלפון לא נראה תקין. נסו שוב, למשל 050-1234567.');
  if (!ANSWERS.includes(status)) return fail('צריך לבחור אם תגיעו.');

  const count = status === 'no' ? 0 : clampInt(data.count, 1, 50, 2);
  const now = new Date().toISOString();
  const { results } = await env.DB.prepare('SELECT id, code, phone FROM guests').all();
  const rows = results || [];
  const match = rows.find((r) => intlPhone(r.phone) === norm);
  let code;
  if (match) {
    code = match.code;
    // A name typed on the general link may be corrected; a name the host imported stays as the host wrote it.
    await env.DB.prepare(
      "UPDATE guests SET name = CASE WHEN grp = ?1 THEN ?2 ELSE name END, status = ?3, count = ?4, note = ?5, source = 'link', answered_at = ?6, invited = MAX(invited, ?7) WHERE id = ?8",
    ).bind(GENERAL_GROUP, name, status, count, note, now, Math.max(count, 1), match.id).run();
  } else {
    code = newCode(new Set(rows.map((r) => r.code)));
    await env.DB.prepare(
      "INSERT INTO guests (code, name, phone, grp, invited, status, count, note, source, answered_at, created_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, 'link', ?9, ?9)",
    ).bind(code, name, phone, GENERAL_GROUP, Math.max(count, 1), status, count, note, now).run();
  }
  return new Response(null, { status: 303, headers: { ...SECURITY_HEADERS, Location: url.origin + '/r/' + code + '?saved=1', 'Cache-Control': 'no-store' } });
}

async function guestPage(env, url, code) {
  const row = await getGuestByCode(env, code);
  if (!row) {
    return html(shell('הלינק לא נמצא', '<h1 class="h">הלינק לא נמצא</h1><p>ייתכן שהלינק הועתק חלקית. כדאי לפתוח אותו שוב מההודעה בוואטסאפ.</p>'), 404);
  }
  const { event, map } = await getSettings(env);
  return html(guestHTML(toGuest(row), event, { edit: url.searchParams.has('edit'), saved: url.searchParams.has('saved'), map, origin: url.origin }));
}

function guestHTML(g, ev, { edit = false, saved = false, error = '', map = null, origin = '' } = {}) {
  const d = dayOf(ev.date);
  const title = ev.boy ? 'בר המצווה של ' + ev.boy : 'בר המצווה';
  const when = d ? weekday(d) + ', ' + dateLong(d) : '';
  const heb = d ? hebDate(d) : '';
  const self = '/r/' + g.code;
  const rsvpBy = dayOf(ev.rsvpBy);
  const showForm = edit || error || g.status === 'pending';

  const head =
    '<meta property="og:type" content="website">' +
    '<meta property="og:title" content="' + esc(title + ' · אישור הגעה') + '">' +
    '<meta property="og:description" content="' + esc(['הזמנה אישית ל' + g.name, when, ev.venue].filter(Boolean).join(' · ')) + '">' +
    ogImage(map, origin) + headlineFont(ev).link;

  let body =
    '<p class="to">הזמנה אישית ל' + esc(g.name) + '</p>' +
    '<h1 class="headline" style="' + headlineFont(ev).style + '">' + esc(headlineOf(ev)) + '</h1>' +
    eventDetailsHTML(ev) +
    (map ? '<a href="/map?v=' + encodeURIComponent(map.v) + '" target="_blank" rel="noopener"><img class="map" src="/map?v=' + encodeURIComponent(map.v) + '" alt="מפת הגעה לאירוע"></a>' : '');

  if (showForm) {
    const opt = (s, label) =>
      '<label class="opt"><input type="radio" name="status" value="' + s + '" id="s-' + s + '"' + (g.status === s ? ' checked' : '') + ' required><span>' + label + '</span></label>';
    const current = g.status === 'yes' || g.status === 'maybe' ? g.count : g.invited;
    const maxCount = Math.max(12, g.invited + 5);
    let options = '';
    for (let i = 1; i <= maxCount; i++) options += '<option value="' + i + '"' + (i === current ? ' selected' : '') + '>' + i + '</option>';
    body +=
      (error ? '<p class="alert">' + esc(error) + '</p>' : '') +
      '<form method="post" action="' + self + '" class="stack">' +
      '<fieldset><legend>תגיעו?</legend>' + opt('yes', 'כן, נגיע') + opt('no', 'לא נוכל להגיע') + opt('maybe', 'עוד לא יודעים') + '</fieldset>' +
      '<div class="count-row"><label for="count">כמה תהיו?</label><select id="count" name="count">' + options + '</select></div>' +
      '<div class="field"><label for="note">הערה (לא חובה)</label><input type="text" id="note" name="note" maxlength="300" value="' + esc(g.note) + '" placeholder="למשל: אחד מאיתנו צמחוני" autocomplete="off"></div>' +
      (rsvpBy ? '<p class="small muted">נשמח לתשובה עד ' + esc(dateShort(rsvpBy)) + '</p>' : '') +
      '<button class="btn primary block" type="submit">שליחת תשובה</button>' +
      '</form>';
  } else {
    const people = g.count === 1 ? 'אורח אחד' : g.count + ' אורחים';
    const copy = {
      yes: ['איזה כיף, נתראה!', 'רשמנו ' + people + '. נשלח תזכורת קרוב לאירוע.'],
      no: ['תודה שעדכנתם', 'חבל שלא תוכלו להגיע. נתגעגע!'],
      maybe: ['תודה על העדכון', 'נשמח לתשובה סופית כשתדעו. אפשר לחזור לאותו לינק בכל זמן.' + (rsvpBy ? ' נשמח לדעת עד ' + dateShort(rsvpBy) + '.' : '')],
    }[g.status];
    body +=
      '<div class="done">' +
      (saved ? '<p class="saved">התשובה נשמרה</p>' : '') +
      '<div class="mark ' + g.status + '">' + CHECK_SVG + '</div>' +
      '<h2 class="h">' + esc(copy[0]) + '</h2><p>' + esc(copy[1]) + '</p>' +
      (g.note ? '<p class="small muted">ההערה שלכם: ' + esc(g.note) + '</p>' : '') +
      (g.status !== 'no' && d
        ? '<div class="links">' +
          (ev.address || ev.venue ? '<a class="btn" href="' + esc(wazeLink(ev)) + '" target="_blank" rel="noopener noreferrer">ניווט בוויז</a>' : '') +
          '<a class="btn" href="' + esc(calLink(ev)) + '" target="_blank" rel="noopener noreferrer">יומן גוגל</a>' +
          '<a class="btn" href="' + self + '/event.ics">יומן אייפון</a>' +
          '</div>'
        : '') +
      '<a class="btn ghost" href="' + self + '?edit=1">שינוי תשובה</a>' +
      '</div>';
  }
  if (ev.sender) body += '<p class="sign">מחכים לראותכם, ' + esc(ev.sender) + '</p>';
  return shell(title + ' · אישור הגעה', body, head);
}

async function guestSubmit(request, env, url, code) {
  const row = await getGuestByCode(env, code);
  const isJSON = (request.headers.get('Content-Type') || '').includes('application/json');
  if (!row) return isJSON ? json({ error: 'not found' }, 404) : guestPage(env, url, code);

  let data = {};
  if (isJSON) data = (await readJSON(request)) || {};
  else { try { data = Object.fromEntries(await request.formData()); } catch { data = {}; } }

  const status = String(data.status || '');
  if (!ANSWERS.includes(status)) {
    if (isJSON) return json({ error: 'status must be yes, no or maybe' }, 400);
    const { event, map } = await getSettings(env);
    return html(guestHTML(toGuest(row), event, { error: 'צריך לבחור אם תגיעו.', map, origin: url.origin }), 400);
  }
  const count = status === 'no' ? 0 : clampInt(data.count, 1, 50, row.invited);
  const note = str(data.note, 300).trim();
  await env.DB.prepare("UPDATE guests SET status = ?1, count = ?2, note = ?3, source = 'link', answered_at = ?4 WHERE id = ?5")
    .bind(status, count, note, new Date().toISOString(), row.id).run();

  if (isJSON) return json({ ok: true });
  return new Response(null, { status: 303, headers: { ...SECURITY_HEADERS, Location: url.origin + '/r/' + code + '?saved=1', 'Cache-Control': 'no-store' } });
}

function icsEscape(s) {
  return String(s || '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
}
function icsFold(line) {
  // lines may be at most 75 octets; fold without splitting a multi-byte character
  const out = [];
  let cur = '', bytes = 0;
  for (const ch of line) {
    const b = enc.encode(ch).length;
    if (bytes + b > (out.length ? 74 : 75)) { out.push(cur); cur = ''; bytes = 0; }
    cur += ch; bytes += b;
  }
  out.push(cur);
  return out.join('\r\n ');
}
async function guestIcs(env, code) {
  const row = await getGuestByCode(env, code);
  const { event: ev } = await getSettings(env);
  if (!row || !dayOf(ev.date)) return new Response('Not found', { status: 404, headers: SECURITY_HEADERS });
  const ymd = ev.date.replace(/-/g, '');
  const t = /^\d{2}:\d{2}$/.test(ev.time) ? ev.time.replace(':', '') : '1900';
  const stamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d+Z$/, 'Z');
  const lines = [
    'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//bar-mitzvah-rsvp//HE', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH',
    'BEGIN:VEVENT',
    'UID:' + ymd + '-' + code + '@bar-mitzvah-rsvp',
    'DTSTAMP:' + stamp,
    'DTSTART;TZID=Asia/Jerusalem:' + ymd + 'T' + t + '00',
    'DTEND;TZID=Asia/Jerusalem:' + ymd + 'T235900',
    'SUMMARY:' + icsEscape(ev.boy ? 'בר המצווה של ' + ev.boy : 'בר המצווה'),
    'LOCATION:' + icsEscape([ev.venue, ev.address].filter(Boolean).join(', ')),
    'END:VEVENT', 'END:VCALENDAR',
  ];
  return new Response(lines.map(icsFold).join('\r\n') + '\r\n', {
    headers: { ...SECURITY_HEADERS, 'Content-Type': 'text/calendar; charset=utf-8', 'Content-Disposition': 'attachment; filename="bar-mitzvah.ics"', 'Cache-Control': 'no-store' },
  });
}

/* ------------------------------------------------------------------ admin API */

async function stateJSON(env, url) {
  const [settings, rows, baseline] = await Promise.all([
    getSettings(env),
    env.DB.prepare('SELECT * FROM guests ORDER BY name').all(),
    getBaseline(env),
  ]);
  const guests = (rows.results || []).map((r) => ({ ...toGuest(r), locked: isLocked(baseline, r.id) }));
  return { ...settings, defaults: DEFAULT_TPL, base: url.origin, guests };
}

function dupKey(name, phone) {
  const p = intlPhone(phone);
  return p ? 'p:' + p : 'n:' + String(name).trim();
}

async function api(request, env, url) {
  const p = url.pathname;
  const method = request.method;

  if (p === '/api/state' && method === 'GET') return json(await stateJSON(env, url));

  if (p === '/api/settings' && method === 'PUT') {
    const body = await readJSON(request);
    if (!body) return json({ error: 'invalid JSON' }, 400);
    const s = await getSettings(env);
    if (body.event && typeof body.event === 'object') {
      for (const k of Object.keys(DEFAULT_EVENT)) if (k in body.event) s.event[k] = str(body.event[k], 200).trim();
      for (const k of ['date', 'rsvpBy']) if (s.event[k] && !dayOf(s.event[k])) s.event[k] = '';
      if (!HEADLINE_FONTS[s.event.font]) s.event.font = 'rubik';
      if (s.event.time && !/^\d{2}:\d{2}$/.test(s.event.time)) s.event.time = '';
    }
    if (body.tpl && typeof body.tpl === 'object') {
      for (const k of Object.keys(DEFAULT_TPL)) if (k in body.tpl) s.tpl[k] = str(body.tpl[k], 3000, true);
    }
    const upsert = UPSERT;
    await env.DB.batch([
      env.DB.prepare(upsert).bind('event', JSON.stringify(s.event)),
      env.DB.prepare(upsert).bind('tpl', JSON.stringify(s.tpl)),
    ]);
    return json({ ok: true, event: s.event, tpl: s.tpl });
  }

  if (p === '/api/guests' && method === 'POST') {
    const body = await readJSON(request);
    if (!body || !Array.isArray(body.guests)) return json({ error: 'guests array required' }, 400);
    if (body.guests.length > 3000) return json({ error: 'too many rows' }, 400);
    const replace = body.replace === true;
    const { results: existing } = await env.DB.prepare('SELECT code, name, phone FROM guests').all();
    const taken = new Set((existing || []).map((r) => r.code));
    const seen = new Set(replace ? [] : (existing || []).map((r) => dupKey(r.name, r.phone)));
    const now = new Date().toISOString();
    const stmts = replace ? [env.DB.prepare('DELETE FROM guests')] : [];
    const newCodes = [];
    let added = 0, skipped = 0;
    for (const raw of body.guests) {
      const name = str(raw && raw.name, 120).trim();
      if (!name) { skipped++; continue; }
      const phone = str(raw.phone, 40).trim();
      const key = dupKey(name, phone);
      if (seen.has(key)) { skipped++; continue; }
      seen.add(key);
      const code = newCode(taken);
      const group = str(raw.group, 60).trim();
      if (group !== TEST_GROUP) newCodes.push(code);
      stmts.push(
        env.DB.prepare('INSERT INTO guests (code, name, phone, grp, invited, created_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6)')
          .bind(code, name, phone, group, clampInt(raw.invited, 1, 50, 2), now),
      );
      added++;
    }
    if (stmts.length) await env.DB.batch(stmts);
    // Imported invitations join the reset starting point (a full replace starts a new one).
    if (newCodes.length || replace) {
      let base = replace ? null : await getBaseline(env);
      if (!base) {
        base = { saved: now, rows: {} };
        if (!replace) {
          // First starting point on a list that already existed: keep its invitations, as unanswered.
          const { results: old } = await env.DB.prepare('SELECT * FROM guests').all();
          for (const r of old || []) {
            if (r.grp !== GENERAL_GROUP && r.grp !== TEST_GROUP && !newCodes.includes(r.code)) base.rows[String(r.id)] = { s: 'pending', c: 0, src: null, at: null, note: '', inv: r.invited };
          }
        }
      }
      if (newCodes.length) {
        const { results: fresh } = await env.DB.prepare('SELECT * FROM guests WHERE code IN (SELECT value FROM json_each(?1))').bind(JSON.stringify(newCodes)).all();
        for (const r of fresh || []) base.rows[String(r.id)] = baselineEntry(r);
      }
      base.saved = now;
      await saveBaseline(env, base);
    }
    return json({ ok: true, added, skipped, state: await stateJSON(env, url) });
  }

  const m = p.match(/^\/api\/guests\/(\d+)$/);
  if (m && method === 'PATCH') {
    const id = Number(m[1]);
    const row = await env.DB.prepare('SELECT * FROM guests WHERE id = ?1').bind(id).first();
    if (!row) return json({ error: 'not found' }, 404);
    const b = (await readJSON(request)) || {};
    const g = { ...row };
    const now = new Date().toISOString();
    if ('name' in b) { const n = str(b.name, 120).trim(); if (n) g.name = n; }
    if ('phone' in b) g.phone = str(b.phone, 40).trim();
    if ('group' in b) g.grp = str(b.group, 60).trim();
    if ('invited' in b) g.invited = clampInt(b.invited, 1, 50, g.invited);
    if ('note' in b) g.note = str(b.note, 300).trim();
    if ('status' in b && STATUSES.includes(b.status) && b.status !== g.status) {
      g.status = b.status;
      if (g.status === 'pending') { g.source = null; g.answered_at = null; g.count = 0; }
      else {
        g.source = 'manual'; g.answered_at = now;
        if (g.status === 'no') g.count = 0; else if (!g.count) g.count = g.invited;
      }
    }
    if ('count' in b && (g.status === 'yes' || g.status === 'maybe')) g.count = clampInt(b.count, 1, 50, g.count || g.invited);
    if (b.reminderSent === true) { g.reminders = (g.reminders || 0) + 1; g.last_reminder = now; }
    await env.DB.prepare(
      'UPDATE guests SET name = ?1, phone = ?2, grp = ?3, invited = ?4, status = ?5, count = ?6, note = ?7, source = ?8, answered_at = ?9, reminders = ?10, last_reminder = ?11 WHERE id = ?12',
    ).bind(g.name, g.phone, g.grp, g.invited, g.status, g.count, g.note, g.source, g.answered_at, g.reminders, g.last_reminder, id).run();
    if ('invited' in b && g.invited !== row.invited) {
      // The host changed how many are invited: a reset keeps that number.
      const base = await getBaseline(env);
      if (base && base.rows[String(id)]) { base.rows[String(id)].inv = g.invited; await saveBaseline(env, base); }
    }
    return json({ ok: true, guest: toGuest(g) });
  }
  if (m && method === 'DELETE') {
    const id = Number(m[1]);
    await env.DB.prepare('DELETE FROM guests WHERE id = ?1').bind(id).run();
    const base = await getBaseline(env);
    if (base && base.rows[String(id)]) { delete base.rows[String(id)]; await saveBaseline(env, base); }
    return json({ ok: true });
  }

  if (p === '/api/reset/preview' && method === 'GET') {
    const plan = await resetPlan(env);
    const pin = await checkResetPin(env, '');
    const brief = (r) => ({ name: r.name, group: r.grp, status: r.status, count: r.count });
    return json({
      pinSet: pin !== null, hasBaseline: !!plan.base, saved: plan.base ? plan.base.saved || null : null,
      remove: plan.remove.map(brief), revert: plan.revert.map((x) => brief(x.r)), locked: plan.locked.map(brief), keepTotal: plan.keepTotal, keepYes: plan.keepYes,
    });
  }
  if (p === '/api/reset' && method === 'POST') {
    const b = (await readJSON(request)) || {};
    const ok = await checkResetPin(env, str(b.pin, 40).trim());
    if (ok === null) return json({ error: 'no reset code configured' }, 409);
    if (!ok) {
      await new Promise((r) => setTimeout(r, 700)); // slow down guessing
      return json({ error: 'wrong code' }, 422);
    }
    const plan = await resetPlan(env);
    const stmts = [];
    for (const r of plan.remove) stmts.push(env.DB.prepare('DELETE FROM guests WHERE id = ?1').bind(r.id));
    for (const { r, k } of plan.revert) {
      stmts.push(
        env.DB.prepare('UPDATE guests SET status = ?1, count = ?2, source = ?3, answered_at = ?4, note = ?5, invited = ?6, reminders = 0, last_reminder = NULL WHERE id = ?7')
          .bind(STATUSES.includes(k.s) ? k.s : 'pending', clampInt(k.c, 0, 50, 0), k.src == null ? null : String(k.src), k.at == null ? null : String(k.at), String(k.note || ''), clampInt(k.inv, 1, 50, r.invited || 2), r.id),
      );
    }
    if (stmts.length) await env.DB.batch(stmts);
    return json({ ok: true, removed: plan.remove.length, reverted: plan.revert.length, state: await stateJSON(env, url) });
  }

  if (p === '/api/map' && method === 'PUT') {
    const body = await readJSON(request);
    const ok = (img, max) => img && MAP_TYPES.includes(img.type) && typeof img.data === 'string' && img.data.length <= max && /^[A-Za-z0-9+/]+=*$/.test(img.data);
    if (!body || !ok(body.full, 1900000) || !ok(body.thumb, 500000)) return json({ error: 'image missing, too large or not jpeg/png/webp' }, 400);
    const v = Date.now();
    const upsert = 'INSERT INTO settings (key, value) VALUES (?1, ?2) ON CONFLICT(key) DO UPDATE SET value = excluded.value';
    await env.DB.batch([
      env.DB.prepare(upsert).bind('map', JSON.stringify({ type: body.full.type, data: body.full.data })),
      env.DB.prepare(upsert).bind('mapthumb', JSON.stringify({ type: body.thumb.type, data: body.thumb.data })),
      env.DB.prepare(upsert).bind('mapmeta', JSON.stringify({ v })),
    ]);
    return json({ ok: true, map: { v } });
  }
  if (p === '/api/map' && method === 'DELETE') {
    await env.DB.prepare("DELETE FROM settings WHERE key IN ('map', 'mapthumb', 'mapmeta')").run();
    return json({ ok: true, map: null });
  }

  if (p === '/api/export.csv' && method === 'GET') {
    const { results } = await env.DB.prepare('SELECT * FROM guests ORDER BY grp, name').all();
    const cell = (v) => {
      let s = String(v == null ? '' : v);
      if (/^[=@]/.test(s) || /^[+-][^\d]/.test(s)) s = "'" + s; // keep spreadsheet formulas out
      return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
    };
    const header = ['שם', 'טלפון', 'קבוצה', 'סטטוס', 'מגיעים', 'הוזמנו', 'הערה', 'איך ענו', 'מתי ענו', 'תזכורות', 'לינק אישי'];
    const lines = [header.map(cell).join(',')];
    for (const r of results || []) {
      lines.push([
        r.name, r.phone, r.grp, STATUS_HE[r.status] || r.status, r.status === 'yes' || r.status === 'maybe' ? r.count : 0, r.invited, r.note,
        r.source === 'link' ? 'דרך הלינק' : r.source === 'manual' ? 'ידני' : r.source === 'excel' ? 'מהאקסל' : '', r.answered_at ? new Date(r.answered_at).toLocaleString('sv-SE', { timeZone: 'Asia/Jerusalem' }).slice(0, 16) : '',
        r.reminders, url.origin + '/r/' + r.code,
      ].map(cell).join(','));
    }
    return new Response('\uFEFF' + lines.join('\r\n'), {
      headers: { ...SECURITY_HEADERS, 'Content-Type': 'text/csv; charset=utf-8', 'Content-Disposition': 'attachment; filename="rsvp.csv"', 'Cache-Control': 'no-store' },
    });
  }

  return json({ error: 'not found' }, 404);
}
